const envelope = $json;
const supported = new Set(["fan.city_requested", "physical_reward.granted", "ticket.order.refund_recorded", "reward_draw.completed", "reward_draw.winner", "admission.pass.revoked", "proof.anchor.dead"]);
if (!envelope || !supported.has(String(envelope.type)) || envelope.version !== 1) {
  throw new Error('Unsupported CrowdRelay business operations event');
}
const data = envelope.data ?? {};
const clean = (value, fallback = '-') => {
  const text = String(value ?? fallback)
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/(?:token|secret|password|authorization|cookie|email)\s*[:=]\s*\S+/gi, '[REDACTED]')
    .trim();
  return (text || fallback).slice(0, 300);
};
const titles = {
  'fan.city_requested': 'NOWE MIASTO DO MODERACJI',
  'physical_reward.granted': 'NAGRODA FIZYCZNA DO REALIZACJI',
  'ticket.order.refund_recorded': 'ZWROT BILETU ZAREJESTROWANY',
  'reward_draw.completed': 'LOSOWANIE ZAKOŃCZONE',
  'reward_draw.winner': 'ZWYCIĘZCA LOSOWANIA',
  'admission.pass.revoked': 'WEJŚCIÓWKA UNIEWAŻNIONA',
  'proof.anchor.dead': 'PROOF ANCHOR DEAD',
};
const severity = envelope.type === 'proof.anchor.dead' ? 'CRITICAL'
  : envelope.type === 'ticket.order.refund_recorded' ? 'WARNING'
  : 'INFO';
const labels = [
  data.display_name, data.city_slug, data.item_name, data.public_reference,
  data.draw_name, data.draw_slug, data.batch_id, data.event_id,
].filter(Boolean).map(value => clean(value));
const summaryMap = {
  'fan.city_requested': `Miasto: ${clean(data.display_name)} (${clean(data.country_code)}), zgłoszenia: ${clean(data.request_count)}.`,
  'physical_reward.granted': `Nagroda: ${clean(data.item_name ?? data.sku)} · fan ${clean(data.fan_id)}.`,
  'ticket.order.refund_recorded': `Zwrot: ${clean(data.amount_refunded_minor ?? data.refund_gross_minor)} ${clean(data.currency)} · zamówienie ${clean(data.public_reference ?? data.order_id)}.`,
  'reward_draw.completed': `Losowanie ${clean(data.draw_name ?? data.draw_slug)}: ${clean(data.selected_winners)} zwycięzców z ${clean(data.eligible_count)} kandydatów.`,
  'reward_draw.winner': `Losowanie ${clean(data.draw_name ?? data.draw_slug)} · zwycięzca fan ${clean(data.fan_id)}.`,
  'admission.pass.revoked': `Wejściówka ${clean(data.public_reference ?? data.pass_id)} została unieważniona.`,
  'proof.anchor.dead': `Batch ${clean(data.batch_id)} nie został zakotwiczony: ${clean(data.error_kind)}.`,
};
const marker = `CR_EVENT_ID:${envelope.id}`;
const content = [
  `## ${titles[envelope.type]}`,
  `**${severity}** · ${envelope.type}`,
  labels.length ? `Obiekt: ${labels.join(' · ')}` : null,
  summaryMap[envelope.type],
  marker,
].filter(Boolean).join('\n\n').slice(0, 1950);
return [{ json: { marker, content, eventType: envelope.type } }];

const source = $('Validate and build business operations alert').first().json;
const values = $input.all().map(item => item.json);
const messages = values.flatMap(value => Array.isArray(value) ? value : [value]);
const alreadySent = messages.some(message => typeof message?.content === 'string' && message.content.includes(source.marker));
return [{ json: { ...source, alreadySent } }];

